export default function Contact() {
  const links = [
    { label: 'Instagram', url: 'https://www.instagram.com/clareny/' },
    { label: 'TikTok', url: 'https://www.tiktok.com/@clareny' },
    { label: 'Linktree', url: 'https://linktr.ee/clareny' },
  ];

  return (
    <section id="contact" className="contact-section">
      <h2 className="section-title">Contacto</h2>
      <p className="contact-copy">
        Si querés trabajar conmigo, mandame WhatsApp con lo que necesitás y te respondo con una propuesta clara. También podés reservar una videollamada por Discord para hablar ideas, escuchar referencias y definir el proyecto.
      </p>

      <div className="social-links">
        {links.map((link) => (
          <a key={link.label} href={link.url} target="_blank" rel="noreferrer">
            {link.label}
          </a>
        ))}
      </div>

      <div className="contact-grid">
        <a className="btn btn-primary" href="https://wa.me/59800000000" target="_blank" rel="noreferrer">Enviar WhatsApp</a>
        <a className="btn btn-secondary" href="https://calendar.app.google/d58w7kzfTmrHnQ8z9" target="_blank" rel="noreferrer">Ver disponibilidad</a>
        <a className="btn btn-secondary" href="https://discord.com" target="_blank" rel="noreferrer">Entrar a Discord</a>
      </div>
    </section>
  );
}
